def compare_libraries_and_bookshops(libraries, bookshops):
    library_books = set()
    for library in libraries:
        for book in library['books']:
            library_books.add(book)

    bookshop_books = set()
    for bookshop in bookshops:
        for book in bookshop['books']:
            bookshop_books.add(book)

    common_books = library_books.intersection(bookshop_books)
    unique_to_library = library_books.difference(bookshop_books)
    unique_to_bookshop = bookshop_books.difference(library_books)

    return {
        'common_books': len(common_books),
        'unique_to_library': len(unique_to_library),
        'unique_to_bookshop': len(unique_to_bookshop)
    }

```
